#include "esp_camera.h"
#include <WiFi.h>
#include <WebServer.h>
#include "FS.h"
#include "SD_MMC.h"

// Wi-Fi access point
const char* ssid = "SentinelX-Camera";
const char* password = "DrainCam826";

WebServer server(80);

int photoNumber = 0;

// AI-Thinker ESP32-CAM pin configuration
#define PWDN_GPIO_NUM     32
#define RESET_GPIO_NUM    -1
#define XCLK_GPIO_NUM      0
#define SIOD_GPIO_NUM     26
#define SIOC_GPIO_NUM     27

#define Y9_GPIO_NUM       35
#define Y8_GPIO_NUM       34
#define Y7_GPIO_NUM       39
#define Y6_GPIO_NUM       36
#define Y5_GPIO_NUM       21
#define Y4_GPIO_NUM       19
#define Y3_GPIO_NUM       18
#define Y2_GPIO_NUM        5
#define VSYNC_GPIO_NUM    25
#define HREF_GPIO_NUM     23
#define PCLK_GPIO_NUM     22

void handleRoot() {
  String page = R"rawliteral(
  <!DOCTYPE html>
  <html>
  <head>
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Sentinel X</title>
  </head>
  <body style="font-family:Arial;text-align:center;">
    <h1>Sentinel X</h1>
    <h3>Drainage Monitoring Camera</h3>
    <p>Capture a photograph and save it to the microSD card.</p>
    <button style="font-size:20px;padding:12px;"
      onclick="location.href='/capture'">
      Capture and Save Photo
    </button>
  </body>
  </html>
  )rawliteral";

  server.send(200, "text/html", page);
}

void handleCapture() {
  camera_fb_t *fb = esp_camera_fb_get();

  if (!fb) {
    server.send(500, "text/plain",
                "Camera capture failed.");
    return;
  }

  String path = "/drain_" +
                String(++photoNumber) + ".jpg";

  File file = SD_MMC.open(path.c_str(), FILE_WRITE);

  if (!file) {
    esp_camera_fb_return(fb);
    server.send(500, "text/plain",
                "Could not create file on microSD card.");
    return;
  }

  size_t written = file.write(fb->buf, fb->len);
  file.close();

  esp_camera_fb_return(fb);

  if (written == 0) {
    server.send(500, "text/plain",
                "Photo could not be saved.");
    return;
  }

  server.send(200, "text/plain",
              "Photo saved to microSD card: " + path);
}

void setup() {
  Serial.begin(115200);

  // Configure camera
  camera_config_t config;

  config.ledc_channel = LEDC_CHANNEL_0;
  config.ledc_timer = LEDC_TIMER_0;

  config.pin_d0 = Y2_GPIO_NUM;
  config.pin_d1 = Y3_GPIO_NUM;
  config.pin_d2 = Y4_GPIO_NUM;
  config.pin_d3 = Y5_GPIO_NUM;
  config.pin_d4 = Y6_GPIO_NUM;
  config.pin_d5 = Y7_GPIO_NUM;
  config.pin_d6 = Y8_GPIO_NUM;
  config.pin_d7 = Y9_GPIO_NUM;

  config.pin_xclk = XCLK_GPIO_NUM;
  config.pin_pclk = PCLK_GPIO_NUM;
  config.pin_vsync = VSYNC_GPIO_NUM;
  config.pin_href = HREF_GPIO_NUM;

  config.pin_sccb_sda = SIOD_GPIO_NUM;
  config.pin_sccb_scl = SIOC_GPIO_NUM;

  config.pin_pwdn = PWDN_GPIO_NUM;
  config.pin_reset = RESET_GPIO_NUM;

  config.xclk_freq_hz = 20000000;
  config.pixel_format = PIXFORMAT_JPEG;

  if (psramFound()) {
    config.frame_size = FRAMESIZE_SVGA;
    config.jpeg_quality = 12;
    config.fb_count = 2;
  } else {
    config.frame_size = FRAMESIZE_VGA;
    config.jpeg_quality = 15;
    config.fb_count = 1;
  }

  // Initialize camera
  esp_err_t result = esp_camera_init(&config);

  if (result != ESP_OK) {
    Serial.printf("Camera error: 0x%x\n", result);
    return;
  }

  // Initialize microSD card in 1-bit mode
  if (!SD_MMC.begin("/sdcard", true)) {
    Serial.println("microSD initialization failed.");
    return;
  }

  if (SD_MMC.cardType() == CARD_NONE) {
    Serial.println("No microSD card detected.");
    return;
  }

  Serial.println("microSD card ready.");

  // Start Wi-Fi access point
  WiFi.mode(WIFI_AP);
  WiFi.softAP(ssid, password);

  Serial.print("Connect to Wi-Fi: ");
  Serial.println(ssid);

  Serial.print("Open webpage at: ");
  Serial.println(WiFi.softAPIP());

  // Start webpage
  server.on("/", HTTP_GET, handleRoot);
  server.on("/capture", HTTP_GET, handleCapture);

  server.begin();

  Serial.println("Sentinel X camera is ready.");
}

void loop() {
  server.handleClient();
}
